<?php require __DIR__.'/config/bootstrap.php'; ?><!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>登录 · LinguaX</title><link rel="stylesheet" href="assets/css/app.css"></head><body><div class="auth card"><div class="brand">Lingua<span>X</span></div><h1>欢迎回来</h1><form id="form"><input name="email" type="email" placeholder="邮箱" required><input name="password" type="password" placeholder="密码" required><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf())?>"><button class="primary">登录</button></form><div id="msg"></div><a href="register.php">没有账户？注册</a></div><script>form.onsubmit=async e=>{e.preventDefault();let r=await fetch('api/auth.php?action=login',{method:'POST',body:new FormData(form)});let j=await r.json();if(j.ok)location=j.redirect;else msg.textContent=j.message}</script></body></html>
